import{_ as t,o as p,c as a,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"无人收割机上感受智慧农业的脉动","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"无人收割机上感受智慧农业的脉动","date":"2026-06-22T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484950.htm","summary":"6月10日 星期三 晴\\n眼下,齐鲁大地由南到北进入小麦夏收时节。\\n下午,我来到山东省邹平市焦桥镇的无人农场,风从金黄色的麦浪上掠过,空气里飘着小麦的清香,耳边传来多种农机运行的轰鸣声。\\n来这里之前,我惦记着一件事:坐进一台无人驾驶收割机,看看它到底怎样在麦田里“自动”割麦。\\n在无人农场一侧的机库里,有一台红色联合收割机。...\\n","contentHash":"e10817715695c67aa5b52c56f10f8dc0","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-06-22-无人收割机上感受智慧农业的脉动.md","filePath":"news/2026-06-22-无人收割机上感受智慧农业的脉动.md"}'),n={name:"news/2026-06-22-无人收割机上感受智慧农业的脉动.md"};function _(s,e,o,l,d,c){return p(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="无人收割机上感受智慧农业的脉动" tabindex="-1">无人收割机上感受智慧农业的脉动 <a class="header-anchor" href="#无人收割机上感受智慧农业的脉动" aria-label="Permalink to &quot;无人收割机上感受智慧农业的脉动&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484950.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-06-22 摘要: 6月10日 星期三 晴 眼下,齐鲁大地由南到北进入小麦夏收时节。 下午,我来到山东省邹平市焦桥镇的无人农场,风从金黄色的麦浪上掠过,空气里飘着小麦的清香,耳边传来多种农机运行的轰鸣声。 来这里之前,我惦记着一件事:坐进一台无人驾驶收割机,看看它到底怎样在麦田里“自动”割麦。 在无人农场一侧的机库里,有一台红色联合收割机。...</p></blockquote><p>眼下,齐鲁大地由南到北进入小麦夏收时节。</p><p>下午,我来到山东省邹平市焦桥镇的无人农场,风从金黄色的麦浪上掠过,空气里飘着小麦的清香,耳边传来多种农机运行的轰鸣声。</p><p>来这里之前,我惦记着一件事:坐进一台无人驾驶收割机,看看它到底怎样在麦田里“自动”割麦。</p><p>在无人农场一侧的机库里,有一台红色联合收割机。乍一看,它与普通农机差别不大;再走近,机身上“北斗+天通 无人驾驶农机”的字样又提醒我:这不是一台寻常的机器。</p><p>无人农场机库里的无人农机。(受访单位供图)</p><p>“上车后坐稳,不要碰方向盘。”中国科学院齐鲁空天信息研究院工程师焦圣凯在车外提醒。</p><p>我刚坐定,他在手机上轻点几下。驾驶室轻轻一震,收割机迅速启动,车厢外传来发动机均匀的轰鸣声,从机库大门匀速驶出。</p><p>方向盘自己转动起来,而收割机也调整方向,沿机耕道向麦田驶去。割台一点点靠近麦田边缘,像一把宽大的梳子,贴着麦穗推向前方。麦穗被卷入割台,瞬间成为车后颗颗饱满的麦粒。</p><p>不同于普通收割机,在这台无人驾驶收割机的主驾驶座两侧,各有一个显示屏。作业路线、速度、定位状态等参数在屏幕上不断跳动。农田的道路并不平整,可收割机却像由一名经验丰富的农机手在操作,走得稳,也走得直。</p><p>到了地头,收割机减速、转向、掉头,再沿着相邻的作业线继续前进,最终回到机库。整个过程中,我的手始终放在腿上,收割机犹如一辆在马路上穿梭的自动驾驶汽车。</p><p>无人收割机与无人拖拉机进行协同作业。新华社记者李傲秋 摄</p><p>“麦田里没有道路标线,它怎么知道往哪儿走?”我问。</p><p>工程师李朴介绍,依托“北斗+天通”星基高精度定位服务平台,这些农机就能够实现厘米级定位,可根据规划好的路线前进;配合车上的雷达和摄像头等传感器,农机就有了“眼睛”,可以做到自动避障。</p><p>在山东今年的“三夏”生产中,6000多万亩小麦正从南到北、由西向东陆续开镰,截至6月10日17时,收割进度超过57%。全省已调配各类农业机械122万台(套),其中小麦联合收割机17.2万台。</p><p>与这支庞大的农机队伍相比,我眼前正在作业的无人收割机还不是麦田里的“主力军”,却是智慧农机走向规模应用的“探路者”。</p><p>在无人农场的管理平台前,大屏幕上显示着地块、农情、设备和作业进度等信息。李朴介绍,农场通过卫星、无人机、地面传感器等组成农情立体感知网络,实时监测苗情、墒情、长势等信息;智能决策与管理平台再根据数据生成作业建议,调度无人农机执行耕、种、管、收等任务。</p><p>无人农场的管理平台,显示着多种农情数据。(受访单位供图)</p><p>这让我对无人农场有了新的理解。所谓“无人”,并不是田里真的不需要人,而是人的位置正在变化:过去,人更多站在田地中劳作,坐在农机里驾驶;现在,人站到屏幕前,利用技术实现远程调度。</p><p>焦桥镇的这座无人农场,是科技部与山东省联合实施的“北斗星动能”科技示范工程应用场景之一。在我看来,无人农场要回答的问题,不只是一台收割机能不能实现无人驾驶,更是人工智能、北斗导航、遥感监测和智能农机等先进技术能否真正连成一个服务农业生产的链条,更好地保障粮食安全。</p><p>麦田边,在无人农场试验种植的种粮大户杨在城正察看着小麦的长势。“以前种地大多靠老经验,现在靠着空天地监测、处方化精准管护,能实时掌握农情,田间管护更科学。”杨在城告诉我,对于无人农机,他很关心前期投入成本高不高、好不好操作、坏了谁来修、田块不规整能不能用等问题。</p><p>技术人员也坦言,从示范到推广还有不少环节要打通。比如,无人驾驶系统要建立标准,无人农场的运营规模要尝试进一步扩大。</p><p>《加快农业农村现代化“十五五”规划》提出,加快农业人工智能技术创新、应用场景拓展和产业生态营造。这为推进智慧农业发展指明了方向。</p><p>傍晚,麦田里的农机仍在轰鸣。看着远处的无人收割机沿着直线稳定前进,身后留下整齐的收割带,我感受到规划中的内容,正沿着机耕道、穿过麦浪,慢慢成为农民身边的现实。(记者李傲秋)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484950.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',26)])])}const h=t(n,[["render",_]]);export{i as __pageData,h as default};
